-- Instituição financeira deixa de ser um enum e vira uma tabela própria,
-- com nome e ícone (imagem guardada no banco).

CREATE TABLE instituicoes_financeiras (
    id UUID PRIMARY KEY,
    nome VARCHAR(255) NOT NULL,
    icone BYTEA,
    icone_tipo VARCHAR(100),
    CONSTRAINT ck_instituicoes_financeiras_icone CHECK ((icone IS NULL) = (icone_tipo IS NULL))
);

CREATE UNIQUE INDEX uq_instituicoes_financeiras_nome ON instituicoes_financeiras (LOWER(nome));

-- Ícones que o frontend usava até aqui (public/nubank.png e public/caixa.png)
INSERT INTO instituicoes_financeiras (id, nome, icone, icone_tipo) VALUES
    (gen_random_uuid(), 'Nubank', decode('', 'hex'), 'image/png'),
    (gen_random_uuid(), 'Caixa', decode('', 'hex'), 'image/png');

ALTER TABLE metodos_pagamento ADD COLUMN instituicao_financeira_id UUID;

UPDATE metodos_pagamento metodo
SET instituicao_financeira_id = instituicao.id
FROM instituicoes_financeiras instituicao
WHERE UPPER(instituicao.nome) = metodo.instituicao_financeira;

ALTER TABLE metodos_pagamento
    ALTER COLUMN instituicao_financeira_id SET NOT NULL,
    ADD CONSTRAINT fk_metodos_pagamento_instituicao
        FOREIGN KEY (instituicao_financeira_id) REFERENCES instituicoes_financeiras (id),
    DROP CONSTRAINT ck_metodos_pagamento_instituicao,
    DROP COLUMN instituicao_financeira;

CREATE INDEX idx_metodos_pagamento_instituicao_financeira_id ON metodos_pagamento (instituicao_financeira_id);
